∀ {Symbol Object : Type} {inst : LinearOrder Symbol} {encode : Object → List Symbol}
  {decode : List Symbol → Option Object} {decode_encode : ∀ (x : Object), decode (encode x) = some x}
  {shortlex_minimal :
    ∀ (x : Object) (c : List Symbol), decode c = some x → D0.Foundation.VerificationCore.ShortlexLE (encode x) c}
  {encode_1 : Object → List Symbol} {decode_1 : List Symbol → Option Object}
  {decode_encode_1 : ∀ (x : Object), decode_1 (encode_1 x) = some x}
  {shortlex_minimal_1 :
    ∀ (x : Object) (c : List Symbol), decode_1 c = some x → D0.Foundation.VerificationCore.ShortlexLE (encode_1 x) c},
  { encode := encode, decode := decode, decode_encode := decode_encode, shortlex_minimal := shortlex_minimal } =
      { encode := encode_1, decode := decode_1, decode_encode := decode_encode_1,
        shortlex_minimal := shortlex_minimal_1 } →
    encode = encode_1 ∧ decode = decode_1

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (history : List (F.State × E.protocol.Line)),
  W.archive history = List.map W.archiveCode history

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s t : F.State) (l l' : E.protocol.Line),
  W.archiveCode (s, l) = W.archiveCode (t, l') ↔ F.profile s = F.profile t ∧ l = l'

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (history : List (F.State × E.protocol.Line)),
  (W.archive history).length = history.length

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s : F.State) (l l' : E.protocol.Line),
  l ≠ l' → W.archiveCode (s, l) ≠ W.archiveCode (s, l')

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (self : D0.Foundation.VerificationCore.SigmaWitness E), Computable self.coding.canon

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (self : D0.Foundation.VerificationCore.SigmaWitness E), Computable₂ self.coding.delta

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s t : F.State),
  W.coding.delta (W.dmin s) (W.dmin t) = true ↔ F.profile s ≠ F.profile t

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s : F.State), W.coding.canon (W.dmin s) = W.dmin s

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s t : F.State), W.dmin s = W.dmin t ↔ F.profile s = F.profile t

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s : F.State) (c : List W.Symbol),
  W.coding.decode c = some (Sum.inl (D0.Foundation.VerificationCore.representedState E s)) →
    D0.Foundation.VerificationCore.ShortlexLE (W.dmin s) c

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory} {Symbol : Type}
  {symbolFinite : Fintype Symbol} {symbolOrder : LinearOrder Symbol} {symbolCoding : Primcodable Symbol}
  {coding : D0.Foundation.VerificationCore.CodePresentation Symbol (D0.Foundation.VerificationCore.SigmaObject E)}
  {canonical_computable : Computable coding.canon} {comparison_computable : Computable₂ coding.delta} {Symbol_1 : Type}
  {symbolFinite_1 : Fintype Symbol_1} {symbolOrder_1 : LinearOrder Symbol_1} {symbolCoding_1 : Primcodable Symbol_1}
  {coding_1 : D0.Foundation.VerificationCore.CodePresentation Symbol_1 (D0.Foundation.VerificationCore.SigmaObject E)}
  {canonical_computable_1 : Computable coding_1.canon} {comparison_computable_1 : Computable₂ coding_1.delta},
  { Symbol := Symbol, symbolFinite := symbolFinite, symbolOrder := symbolOrder, symbolCoding := symbolCoding,
        coding := coding, canonical_computable := canonical_computable,
        comparison_computable := comparison_computable } =
      { Symbol := Symbol_1, symbolFinite := symbolFinite_1, symbolOrder := symbolOrder_1,
        symbolCoding := symbolCoding_1, coding := coding_1, canonical_computable := canonical_computable_1,
        comparison_computable := comparison_computable_1 } →
    Symbol = Symbol_1 ∧
      symbolFinite ≍ symbolFinite_1 ∧ symbolOrder ≍ symbolOrder_1 ∧ symbolCoding ≍ symbolCoding_1 ∧ coding ≍ coding_1

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (history later : List (List W.Symbol)),
  ∀ n < history.length, W.query (history ++ later) n = W.query history n

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (history : List (F.State × E.protocol.Line)) (n : ℕ),
  W.query (W.archive history) n = Option.map W.archiveCode history[n]?

